  "prompt": "prompts/physics_committee_terra_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B046",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED made quantum-optical control, measurement, and strong light-matter coupling available in a lithographic electrical circuit, opening an exceptionally productive new physical platform.",
        "attribution": "Blais supplied the decisive theoretical architecture, while Wallraff and Schoelkopf established its experimental realization; this is a coherent three-person attribution.",
        "maturity": "The phenomena and methods have been reproduced broadly and underpin a mature field, although their proximity to the 2025 superconducting-circuit prize requires careful assessment of separability.",
        "uncertainties": [
          "The contribution may be judged too closely connected to the 2025 award for macroscopic quantum tunnelling and energy quantization in superconducting circuits."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B044",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction established that fragile quantum systems can in principle support reliable computation through physically profound encoding and fault-tolerance ideas.",
        "attribution": "Shor's code and threshold-era insight, Steane's code constructions, and Kitaev's foundational fault-tolerant framework form a strong though necessarily selective attribution.",
        "maturity": "The theory is long-established and experiments now demonstrate key error-correction ingredients, but fully scalable fault tolerance remains unfinished.",
        "uncertainties": [
          "Whether a principally theoretical information-science advance has sufficiently decisive experimental realization for a Physics prize.",
          "Priority and credit extend beyond three influential contributors."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Optical-lattice quantum simulation provided remarkably clean, controllable realizations of many-body Hamiltonians and transformed experiment in correlated quantum matter.",
        "attribution": "Zoller was central to the conceptual foundations, while Bloch and Greiner led defining experimental advances; the broader contribution of Cirac also deserves serious consideration.",
        "maturity": "The platform is extensively replicated, technically mature, and continues to yield fundamental many-body results.",
        "uncertainties": [
          "The discovery overlaps substantially with the more general atomic quantum-computation and simulation candidate."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B021",
      "proposed_laureates": [
        "Antoine Browaeys",
        "Mark Saffman",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Programmable Rydberg arrays have created a powerful experimental route to engineered interacting quantum systems, combining microscopic control with genuine many-body scale.",
        "attribution": "Browaeys and Lukin drove landmark array experiments, with Saffman providing essential blockade and quantum-information foundations.",
        "maturity": "Multiple laboratories now operate programmable arrays and have verified important simulation and control capabilities.",
        "uncertainties": [
          "The field is comparatively young and its enduring fundamental discoveries remain to be distinguished from technological promise."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B045",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks unite quantum control with precision metrology at an extraordinary level and have changed the practical and conceptual reach of timekeeping.",
        "attribution": "Katori's magic-wavelength lattice-clock concept and Ye's decisive high-precision development provide a compelling two-person account.",
        "maturity": "The performance, reproducibility, and scientific applications are well established across laboratories.",
        "uncertainties": [
          "It must be assessed whether the advance is best recognized as a fundamental discovery rather than an exceptional metrological implementation."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B051",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped-ion quantum computation supplied seminal protocols and unusually precise experimental control of entanglement, making a foundational quantum-information vision physically credible.",
        "attribution": "Cirac and Zoller developed decisive theoretical proposals, and Blatt provided landmark experimental realizations; the selected trio is intellectually well aligned.",
        "maturity": "Ion platforms have repeatedly demonstrated high-fidelity control over decades and remain among the most mature quantum processors.",
        "uncertainties": [
          "This nomination overlaps with the broader atomic quantum-information and optical-lattice simulation claims."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B036",
      "proposed_laureates": [
        "Michael V. Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "Geometric quantum phase is a deep, experimentally consequential reformulation of how quantum evolution carries observable information, with influence across quantum physics.",
        "attribution": "Berry gave the canonical adiabatic geometric phase, while Aharonov's phase-related foundational work substantially broadened the physical conception.",
        "maturity": "The effects are long confirmed in varied systems and are securely embedded in modern quantum and topological physics.",
        "uncertainties": [
          "The relationship between the named geometric and topological phase contributions is broad, and the most appropriate attribution may be more complex than two names."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B041",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Xiao-Gang Wen"
      ],
      "assessment": {
        "nobel_worthiness": "Topological order and long-range entanglement supplied a fundamentally new classification of quantum many-body matter beyond symmetry breaking.",
        "attribution": "Kitaev and Wen made distinct, foundational theoretical contributions that together define the modern concept.",
        "maturity": "The framework is deeply established and motivates extensive experimental searches and engineered realizations, though direct decisive demonstrations of all central implications remain uneven.",
        "uncertainties": [
          "The most definitive experimental manifestations and the appropriate division of theoretical credit remain contested."
        ]
      }
    }
  ]
}
